<?php
require_once __DIR__ . '/db_pdo.php';
require_once __DIR__ . '/config.php';
$universities=[]; $selected=[]; $error='';
try {
  $pdo=youruniPdo();
  $universities=$pdo->query('SELECT id,uni_name,major,region,min_marks,admission_status,image_path,page,source_url,last_verified_at FROM uni ORDER BY uni_name')->fetchAll();
  $ids=$_GET['ids'] ?? [];
  if (!is_array($ids)) $ids=[];
  $ids=array_values(array_unique(array_filter(array_map('intval',$ids),fn($x)=>$x>0)));
  if (count($ids)>3) { $ids=array_slice($ids,0,3); $error='You can compare up to three universities at a time.'; }
  if ($ids) {
    $ph=implode(',',array_fill(0,count($ids),'?'));
    $st=$pdo->prepare("SELECT id,uni_name,major,region,min_marks,admission_status,image_path,page,source_url,last_verified_at FROM uni WHERE id IN ($ph)");
    $st->execute($ids); $items=$st->fetchAll(); $map=[]; foreach($items as $row)$map[(int)$row['id']]=$row;
    foreach($ids as $id) if(isset($map[$id])) $selected[]=$map[$id];
  }
} catch(Throwable $e) { error_log('YourUni compare page: '.$e->getMessage()); $error='The university catalogue could not be loaded. Check your database setup.'; }
function cmpH($v){return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function cmpAdmission($u){$s=$u['admission_status']??'unknown';if($s==='known' && (int)$u['min_marks']>0)return 'Listed minimum marks: '.(int)$u['min_marks'];if($s==='pass_based')return 'Recorded as pass-based; verify official notice';return 'Not verified';}
?>
