<?php if($error): ?><div class="notice"><?=cmpH($error)?></div><?php endif; ?>
<section class="panel"><form method="get"><div class="list"><?php foreach($universities as $u): ?><label class="pick"><input type="checkbox" name="ids[]" value="<?= (int)$u['id'] ?>" <?= in_array((int)$u['id'],array_column($selected,'id'))?'checked':'' ?>><span><strong><?=cmpH($u['uni_name'])?></strong><small><?=cmpH($u['region'])?> · <?=cmpH($u['major'])?></small></span></label><?php endforeach; ?></div><p style="display:flex;gap:10px;flex-wrap:wrap;margin:20px 0 0"><button type="submit">Compare selected</button><a class="btn btn-lite" href="compare.php">Clear selection</a></p></form></section>
<?php if(count($selected)>=2): ?><section><h2>Your comparison</h2><div class="compare-grid"><?php foreach($selected as $u): ?><article class="compare-card"><img src="<?=cmpH($u['image_path'])?>" alt="<?=cmpH($u['uni_name'])?>" loading="lazy"><h3><?=cmpH($u['uni_name'])?></h3><p class="small"><?=cmpH($u['region'])?></p><div class="comp-row"><span>Listed fields</span><?=cmpH($u['major'])?></div><div class="comp-row"><span>Admission requirements</span><?=cmpH(cmpAdmission($u))?></div><div class="comp-row"><span>Last verified</span><?=cmpH($u['last_verified_at'] ?: 'Not recorded')?></div><div class="comp-row"><span>Official source</span><?php if(!empty($u['source_url'])): ?><a href="<?=cmpH($u['source_url'])?>" target="_blank" rel="noopener">Open source ↗</a><?php else: ?>No source recorded<?php endif; ?></div><div class="comp-row"><a class="btn" href="<?=cmpH($u['page'])?>">University details</a></div></article><?php endforeach; ?></div></section><?php elseif(count($selected)===1): ?><p class="muted">Select at least one more university to compare.</p><?php endif; ?></main><footer class="yu-site-footer"><span><strong>YourUni</strong> · Explore Myanmar's Universities</span><span><a href="About.html">About Us</a> · <a href="donate.php">Support YourUni</a></span></footer><script src="assets/youruni-global.js" defer></script><script>document.querySelector('form').addEventListener('submit',function(e){const n=this.querySelectorAll('input[name="ids[]"]:checked').length;if(n>3){e.preventDefault();alert('Choose no more than three universities.');}});</script></body></html>
